text:
{
  "units": [
    {
      "issue": {
        "id": "U00",
        "role": "main",
        "statement": "截至2023-08-01各事件完成后，三笔债务的未偿范围、各主体可被即时请求的责任及重叠责任边界。"
      },
      "decisive_facts": [
        "全部材料为显著标注的虚构情景；单方法律主张不属于认可事实或法院认定。",
        "结算不计2023-08-01当日利息；SP-01于09:20到账，第三人文书于13:40签署，追加请求于16:10提出。",
        "甲请求乙清偿A返还债务及B、C合法未偿余额，并分别向保证人和辛提出请求；不请求保证合同无效后的过错赔偿。",
        "最终分项取分后汇总；辛的份额依S14另定的取分顺序计算。"
      ],
      "support_spans": {
        "facts": [
          {
            "span_id": "S12",
            "anchor": "最终诉请及单方法律主张"
          },
          {
            "span_id": "S13",
            "anchor": "09:20实际付款；最终核对到账后的剩余余额"
          },
          {
            "span_id": "S14",
            "anchor": "13:40签署、16:10追加请求及份额取分条款"
          }
        ],
        "rules": [
          {
            "source_id": "civil-code-2020",
            "provisions": ["157", "552", "560", "561", "682", "687", "688", "697"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
          }
        ]
      },
      "dependencies": [
        {
          "on": "U01",
          "relation": "确定A返还债务及丁的保证合同责任边界"
        },
        {
          "on": "U02",
          "relation": "确定B付款前合法本息及计算基准"
        },
        {
          "on": "U03",
          "relation": "确定C付款前本金、利息、费用及计算基准"
        },
        {
          "on": "U04",
          "relation": "确定戊、庚保证是否存续及对外范围"
        },
        {
          "on": "U05",
          "relation": "区分己保证存续与即时承担责任"
        },
        {
          "on": "U06",
          "relation": "确定SP-01抵充对象及付款后余额"
        },
        {
          "on": "U07",
          "relation": "确定辛加入范围、乙原债务及己保证是否变化"
        }
      ],
      "answerability": {
        "status": "supported_structure_amounts_pending",
        "supported_states": [
          "可形成乙的债务余额与丁、戊、庚、己、辛责任的分项核对结构。",
          "同一债务由多个主体负责，不构成可重复收取的新增债权；债务总额与各主体责任上限应分别展示。"
        ],
        "pending_checks": [
          "逐笔日数、十进制定点运算、结息上限比较、付款抵充及最终取分尚需独立复算。"
        ],
        "boundary": "这是题设和所附规范支持的待核验责任结构，不是实际裁判结论，也未形成金额金标。"
      }
    },
    {
      "issue": {
        "id": "U01",
        "role": "dependency",
        "statement": "A的合同效力、实际财产返还范围与丁的从属保证效力。"
      },
      "decisive_facts": [
        "A于2022-03-11签订，资金为甲套取的银行信贷资金；乙不知来源且利率为6%。",
        "票面160000元，实际交付143089.00元；已有返还20261.00元。",
        "如合同无效，双方约定既有返还全部冲抵财产返还；甲不请求票面未交付差额及其他无效后赔偿。",
        "丁为A提供连带保证；不存在题设之外的法律例外。"
      ],
      "support_spans": {
        "facts": [
          {
            "span_id": "S01",
            "anchor": "银行资金来源、实际到账、乙不知情及丁保证"
          },
          {
            "span_id": "S02",
            "anchor": "附条件清算约定、此前返还及重复到账收据"
          },
          {
            "span_id": "S12",
            "anchor": "不请求保证合同无效后的过错赔偿"
          }
        ],
        "rules": [
          {
            "source_id": "lending-2020-12",
            "provisions": ["13", "31"],
            "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html"
          },
          {
            "source_id": "civil-code-2020",
            "provisions": ["157", "682"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
          }
        ]
      },
      "dependencies": [],
      "answerability": {
        "status": "supported",
        "supported_states": [
          "依适用版本第十三条，A的无效判断不以高利转贷或者乙事先知情为必要条件。",
          "返还范围以实际交付扣除已返还财产为基础，同一到账交易的收据不构成追加交付。",
          "A无效导致丁的保证合同无效，不能据该保证合同请求丁承担有效保证责任。"
        ],
        "boundary": "不能将未请求且缺少过错材料的无效保证赔偿认定为零，亦不能扩展计算该项赔偿。"
      }
    },
    {
      "issue": {
        "id": "U02",
        "role": "dependency",
        "statement": "B预扣利息后的初始本金、逐期合法结息与整体本息上限。"
      },
      "decisive_facts": [
        "B于2022-01-12实际交付并成立；票面198783.00元，预扣12493.00元，实际到账186290.00元。",
        "合同年利率13.20%，题设确认合同成立时一年期LPR为3.70%。",
        "三次归档日为2022-07-06、2022-10-17、2023-01-09，均无新增交付。",
        "双方约定逐期结息，不构成债务更新，沿用原利率及原LPR，实际自然日除以365，计算过程不提前取分。",
        "B展期至2023-06-30，最终请求包括截至结算日的可保护本息。"
      ],
      "support_spans": {
        "facts": [
          {
            "span_id": "S03",
            "anchor": "实际交付、成立与起息日期、利率及LPR"
          },
          {
            "span_id": "S04",
            "anchor": "逐次结算、无债务更新及精度约定"
          },
          {
            "span_id": "S05",
            "anchor": "三次归档纸面金额及新增交付0元"
          },
          {
            "span_id": "S06",
            "anchor": "原到期日及展期"
          },
          {
            "span_id": "S12",
            "anchor": "B全部可保护本息的未偿余额"
          }
        ],
        "rules": [
          {
            "source_id": "civil-code-2020",
            "provisions": ["670", "679", "680"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
          },
          {
            "source_id": "lending-2020-12",
            "provisions": ["25", "26", "27", "28"],
            "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html"
          }
        ]
      },
      "dependencies": [],
      "answerability": {
        "status": "supported_calculation_pending",
        "supported_states": [
          "初始本金为实际交付186290.00元，不是票面金额。",
          "合同利率13.20%低于题设LPR四倍14.80%；纸面归档额仍须按合法本金和可计入利息重建，不能直接照录。",
          "逐期结息所得候选本息还须接受第二十七条第二款的整体上限检验。",
          "到期后利息适用所附第二十八条，不因展期或归档重新选择合同成立时LPR。"
        ],
        "pending_checks": [
          "各期合法结息金额、逾期期间计算及整体上限比较。",
          "SP-01清偿前的合法本息与清偿后的本金、利息归属。"
        ]
      }
    },
    {
      "issue": {
        "id": "U03",
        "role": "dependency",
        "statement": "C跨规范时点的合法利息、逐笔付款抵充与重复或未执行记录的处理。"
      },
      "decisive_facts": [
        "C于2019-02-07交付226970.00元并成立，约定年利率23.50%，到期日2022-12-15，逾期沿用该利率。",
        "甲明确请求按当时司法解释计算截至2020-08-19的利息；题设确认各次起诉时一年期LPR为3.25%。",
        "原合同约定费用、依法可请求利息、本金的清偿顺序；T-02另有有效的本金优先补充协议。",
        "T-01至T-07均已结算；T-01截图与收据为同一交易，X-01未执行且未到账。",
        "费用1680元于2019-04-17发生并到期，依法可收取；利息按未偿本金、实际自然日除以365单利计算。"
      ],
      "support_spans": {
        "facts": [
          {
            "span_id": "S07",
            "anchor": "成立日期、利率、费用、单利规则及过渡适用请求"
          },
          {
            "span_id": "S08",
            "anchor": "七笔已结算付款的日期、金额及C债务指定"
          },
          {
            "span_id": "S09",
            "anchor": "原清偿顺序、T-02补充协议及其他单方备注"
          },
          {
            "span_id": "S11",
            "anchor": "T-01重复记录及X-01未执行通知"
          }
        ],
        "rules": [
          {
            "source_id": "lending-2015",
            "provisions": ["26"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/15146.html"
          },
          {
            "source_id": "lending-2020-12",
            "provisions": ["25", "28", "31"],
            "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html"
          },
          {
            "source_id": "civil-code-2020",
            "provisions": ["561"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
          }
        ]
      },
      "dependencies": [],
      "answerability": {
        "status": "supported_calculation_pending",
        "supported_states": [
          "截至2020-08-19的相应期间可按约定23.50%计算；2020-08-20起按题设起诉时LPR四倍13.00%的保护范围计算。",
          "T-02适用双方本金优先约定；其他付款不能仅凭乙单方备注改变原合同清偿顺序。",
          "T-01只计一次，X-01不产生已清偿金额。",
          "每次付款后应更新未偿本金、费用及利息；未付利息不再生息。"
        ],
        "pending_checks": [
          "跨2020-08-20的计息分段、七笔付款的项目归属及付款前余额。"
        ],
        "boundary": "2019年的清偿顺序直接依据明确合同及补充协议，不倒推适用2021年才施行的第五百六十一条。"
      }
    },
    {
      "issue": {
        "id": "U04",
        "role": "dependency",
        "statement": "戊、庚的保证类型、期间内分别行权及内部追偿约定对对外责任的影响。"
      },
      "decisive_facts": [
        "戊、庚在同一原件上各自承诺以连带保证覆盖全部B债务，并约定内部相互追偿、各分担50%。",
        "二人同意合法结息机制，但未书面同意将2023-01-12到期的B展期；期间条款均为直至本息还清。",
        "针对戊的给付诉状于2023-07-07实际送达，2023-07-09撤诉且未放弃实体权利。",
        "甲于2023-07-06向庚提出完整给付请求并实际到达。",
        "二人有充分履行能力，不存在其他影响内部追偿的事由。"
      ],
      "support_spans": {
        "facts": [
          {
            "span_id": "S06",
            "anchor": "共同保证原件、展期、分别行权记录及相互追偿条款"
          },
          {
            "span_id": "S12",
            "anchor": "戊关于内部50%等于对外50%的单方法律主张"
          }
        ],
        "rules": [
          {
            "source_id": "civil-code-2020",
            "provisions": ["688", "691", "692", "693", "695"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
          },
          {
            "source_id": "guarantee-2020",
            "provisions": ["13", "25", "29", "31", "32"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/282721.html"
          }
        ]
      },
      "dependencies": [
        {
          "on": "U02",
          "relation": "保证覆盖以B依法可保护的本息为界，不覆盖未经核验的纸面膨胀额"
        }
      ],
      "answerability": {
        "status": "supported",
        "supported_states": [
          "二人均为连带责任保证；保证期间按原到期日计算六个月，至2023-07-12，未同意的展期不改变该期间。",
          "戊在期间内收到诉状，随后撤诉不否定已行权；庚也分别在期间内收到请求。",
          "不存在因甲漏向庚行权而导致戊丧失追偿权的题设基础。",
          "内部各50%不改变原件约定的各自对外覆盖全部合法B债务；庚主张保证消灭和戊主张相应减免均无题设支持。"
        ],
        "boundary": "最终可请求金额须随SP-01抵充后的B余额确定；不得把两人的责任上限相加为双倍B债权。"
      }
    },
    {
      "issue": {
        "id": "U05",
        "role": "dependency",
        "statement": "己的保证适用时间、类型、撤诉后再诉的期间效果与先诉抗辩。"
      },
      "decisive_facts": [
        "己的保证于2022-02-07成立，约定乙不能履行、无力偿还时才清偿，未另定保证期间。",
        "C到期日为2022-12-15；甲2023-06-08起诉乙，2023-06-12撤诉，2023-06-14再诉并获受理。",
        "2023-06-25己只确认收到催告，明确不确认付款义务，无新保证协商。",
        "乙有可供执行财产，案件未审判、未执行，己未放弃先诉抗辩且无题设所列例外。"
      ],
      "support_spans": {
        "facts": [
          {
            "span_id": "S07",
            "anchor": "C原合同到期日及2022年保证不构成新借款"
          },
          {
            "span_id": "S10",
            "anchor": "己保证原文、两次诉讼及收件签名"
          },
          {
            "span_id": "S12",
            "anchor": "己主张保证类型随2019年借款适用旧规则"
          },
          {
            "span_id": "S14",
            "anchor": "截至截日未审判、未执行及无先诉抗辩例外"
          }
        ],
        "rules": [
          {
            "source_id": "civil-code-2020",
            "provisions": ["687", "691", "692", "693", "1260"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
          },
          {
            "source_id": "guarantee-2020",
            "provisions": ["25", "31", "34"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/282721.html"
          }
        ]
      },
      "dependencies": [],
      "answerability": {
        "status": "supported",
        "supported_states": [
          "保证合同在2022年成立，不能仅因主借款成立于2019年而改用旧保证规则；原文支持一般保证。",
          "六个月保证期间至2023-06-15；撤诉后于2023-06-14期间内再诉，支持原保证责任继续存续。",
          "仅确认收件不构成新的保证承诺，本情景也不需要依该签名恢复原保证。",
          "保证存续不等于己须立即支付；现有事实支持己行使先诉抗辩。"
        ],
        "boundary": "不能将当前不能即时请求己付款解释为C无担保，亦不能认定己永久免责。"
      }
    },
    {
      "issue": {
        "id": "U06",
        "role": "dependency",
        "statement": "按09:20付款时的担保状态及双方附件，确定SP-01在B、C之间的抵充。"
      },
      "decisive_facts": [
        "SP-01实际到账25000.00元，双方限定只清偿B、C，未在二者之间指定。",
        "双方约定：两债均到期且有同等资信的全额保证时，优先清偿付款日依法可强制请求年利率较高者。",
        "B、C没有保证之外的担保，各保证人的资信与依法存续范围内的担保履行能力无争议。",
        "第三人文书签于该付款之后。"
      ],
      "support_spans": {
        "facts": [
          {
            "span_id": "S13",
            "anchor": "付款范围、未指定债务及双方签署的利率比较附件"
          },
          {
            "span_id": "S06",
            "anchor": "B保证人的覆盖范围及资信"
          },
          {
            "span_id": "S10",
            "anchor": "己保证及程序状态"
          },
          {
            "span_id": "S14",
            "anchor": "付款后13:40才签署第三人文书"
          }
        ],
        "rules": [
          {
            "source_id": "civil-code-2020",
            "provisions": ["560", "561", "687"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
          }
        ]
      },
      "dependencies": [
        {
          "on": "U04",
          "relation": "确定付款时B仍有覆盖全部合法债务的保证"
        },
        {
          "on": "U05",
          "relation": "确定付款时C保证存续，先诉抗辩不等于担保消灭"
        },
        {
          "on": "U02",
          "relation": "提供B依法可请求的13.20%年利率及付款前余额"
        },
        {
          "on": "U03",
          "relation": "提供C依法可请求的13.00%年利率及付款前余额"
        }
      ],
      "answerability": {
        "status": "supported_allocation_calculation_pending",
        "supported_states": [
          "题设支持适用双方附件的条件；应比较受保护利率，而非C名义23.50%的利率。",
          "B的13.20%高于C的13.00%，SP-01应优先抵充B。",
          "选定B后，还需确定该笔付款在B内部利息与本金之间的清偿归属。",
          "13:40的后续文书不能反向改变09:20已经发生的抵充。"
        ],
        "pending_checks": [
          "复核付款前B余额及内部抵充后的本息分项，避免提前取分影响结果。"
        ]
      }
    },
    {
      "issue": {
        "id": "U07",
        "role": "dependency",
        "statement": "《代偿支持》的实体性质、辛的责任范围及其对乙、己的影响。"
      },
      "decisive_facts": [
        "甲乙辛共同约定：辛就SP-01结算后C尚欠各项的50%与乙一并负担，甲可单独向辛请求。",
        "辛付款不以先向乙追索、执行或乙无力偿还为条件；文件明确不免除乙原合同义务。",
        "没有新增交付，原交付日期、利率及到期日未变。",
        "份额以C本金、利息、费用分别取分后合计为基数，50%再取分；签署后无付款。"
      ],
      "support_spans": {
        "facts": [
          {
            "span_id": "S14",
            "anchor": "《代偿支持》义务正文、取分条款及无新增交付"
          },
          {
            "span_id": "S12",
            "anchor": "甲关于标题决定责任及乙关于后文书改变早先抵充的主张"
          }
        ],
        "rules": [
          {
            "source_id": "civil-code-2020",
            "provisions": ["552", "687", "697"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
